import { ref, onMounted } from "vue";
import { useRoute, useRouter } from "vue-router";
import { ElButton, ElDialog, ElInput, ElMessage, ElAvatar } from "element-plus";
import axios from "axios";
import { useStore } from "vuex";
const API_BASE_URL = "http://localhost:5000";
export default {
  __name: 'ProductPage',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const paymentPassword = ref("");
    const route = useRoute();
    const router = useRouter();
    const store = useStore();
    const product = ref({
      id: null,
      name: "",
      price: 0,
      image: "",
      description: "",
      stock: 0
    });
    const optionsVisible = ref(false);
    const isDialogVisible = ref(false);
    const isPasswordDialogVisible = ref(false);
    const isGroupBuyDialogVisible = ref(false);
    const currentGroup = ref(null);
    const availableGroups = ref([]);
    const inviteCode = ref("");
    const groupBuyAction = ref(""); // 'create' or 'join'
    const timers = ref({});
    const buyDialogVisible = ref(false);
    const quantity = ref(1);
    const selectedCouponId = ref(null);
    const availableCoupons = ref([]);
    const buying = ref(false);

    // 获取商品详细信息
    onMounted(async () => {
      await fetchProductDetails();
      await fetchAvailableGroups();
    });
    const fetchProductDetails = async () => {
      const productId = route.params.id;
      try {
        const response = await axios.get(`${API_BASE_URL}/api/products/${productId}`);
        if (response.data.code === 200) {
          product.value = response.data.data;
          product.value.price = parseFloat(product.value.price) || 0;
        }
      } catch (error) {
        ElMessage.error("获取商品详情失败");
      }
    };
    const fetchAvailableGroups = async () => {
      try {
        const token = localStorage.getItem("token");
        if (!token) {
          ElMessage.error("请先登录");
          return;
        }
        const response = await axios.get(`${API_BASE_URL}/api/group-buys/available?productId=${product.value.id}`, {
          headers: {
            Authorization: `Bearer ${token}`
          }
        });
        if (response.data.code === 200) {
          availableGroups.value = response.data.data;
        }
      } catch (error) {
        console.error("获取可用拼团失败:", error);
      }
    };
    const showGroupBuyDialog = () => {
      isGroupBuyDialogVisible.value = true;
      optionsVisible.value = false;
      fetchAvailableGroups();
    };
    const createGroup = () => {
      groupBuyAction.value = "create";
      isPasswordDialogVisible.value = true;
    };
    const joinGroup = group => {
      groupBuyAction.value = "join";
      inviteCode.value = group.inviteCode;
      isPasswordDialogVisible.value = true;
    };
    const joinGroupByCode = () => {
      if (!inviteCode.value) {
        ElMessage.error("请输入邀请码");
        return;
      }
      groupBuyAction.value = "join";
      isPasswordDialogVisible.value = true;
    };
    const handlePaymentSubmit = async () => {
      console.log("提交支付时的购买方式:", groupBuyAction.value);
      if (!paymentPassword.value) {
        ElMessage.error("请输入支付密码");
        return;
      }
      try {
        const token = localStorage.getItem("token");
        if (!token) {
          ElMessage.error("请先登录");
          return;
        }

        // 获取用户余额
        const userResponse = await axios.get(`${API_BASE_URL}/api/user/balance`, {
          headers: {
            Authorization: `Bearer ${token}`
          }
        });
        if (userResponse.data.code !== 200) {
          throw new Error("获取用户余额失败");
        }
        const userBalance = userResponse.data.data;
        const discountedPrice = product.value.price * 0.8; // 拼团价格（8折）

        // 检查余额是否足够
        if (userBalance < discountedPrice) {
          ElMessage.error(`账户余额不足，需要 ¥${discountedPrice.toFixed(2)}，当前余额 ¥${userBalance.toFixed(2)}`);
          return;
        }
        let response;
        if (groupBuyAction.value === "create") {
          response = await axios.post(`${API_BASE_URL}/api/group-buys/create`, {
            productId: product.value.id,
            paymentPassword: paymentPassword.value,
            paymentAmount: discountedPrice
          }, {
            headers: {
              Authorization: `Bearer ${token}`
            }
          });
          if (response.data.code === 200) {
            currentGroup.value = response.data.data;
            isPasswordDialogVisible.value = false;
            if (currentGroup.value?.remainingSeconds !== undefined) {
              startCountdown();
            }
            ElMessage.success("创建拼团成功！已支付拼团价格");
          }
        } else if (groupBuyAction.value === "join") {
          response = await axios.post(`${API_BASE_URL}/api/group-buys/join`, {
            inviteCode: inviteCode.value,
            paymentPassword: paymentPassword.value,
            paymentAmount: discountedPrice
          }, {
            headers: {
              Authorization: `Bearer ${token}`
            }
          });
          if (response.data.code === 200) {
            currentGroup.value = response.data.data;
            isPasswordDialogVisible.value = false;
            if (currentGroup.value?.remainingSeconds !== undefined) {
              startCountdown();
            }
            ElMessage.success("加入拼团成功！已支付拼团价格");
          }
        } else {
          // 单独购买的处理逻辑
          console.log("开始处理单独购买...");
          response = await axios.post(`${API_BASE_URL}/api/orders`, {
            userId: store.getters.userId,
            productId: product.value.id,
            quantity: 1,
            paymentAmount: product.value.price,
            paymentPassword: paymentPassword.value
          }, {
            headers: {
              Authorization: `Bearer ${token}`
            }
          });
          if (response.data.code === 200) {
            isPasswordDialogVisible.value = false;
            paymentPassword.value = "";
            groupBuyAction.value = "";
            ElMessage.success("购买成功！");
            setTimeout(() => {
              router.push("/orders");
            }, 500);
          }
        }
      } catch (error) {
        console.error("支付失败:", error);
        ElMessage.error(error.response?.data?.message || "支付失败，请稍后重试");
      } finally {
        paymentPassword.value = "";
      }
    };
    const copyInviteCode = () => {
      if (currentGroup.value?.inviteCode) {
        navigator.clipboard.writeText(currentGroup.value.inviteCode).then(() => ElMessage.success("邀请码已复制到剪贴板")).catch(() => ElMessage.error("复制失败，请手动复制"));
      }
    };
    const formatTime = seconds => {
      if (seconds == null || isNaN(seconds)) return "00:00:00";
      const hours = Math.floor(seconds / 3600);
      const minutes = Math.floor(seconds % 3600 / 60);
      const remainingSeconds = seconds % 60;
      return `${hours.toString().padStart(2, "0")}:${minutes.toString().padStart(2, "0")}:${remainingSeconds.toString().padStart(2, "0")}`;
    };
    const startCountdown = () => {
      console.log(`开始拼团${currentGroup.value.id}的倒计时`);
      const timer = setInterval(async () => {
        if (!currentGroup.value) {
          clearInterval(timer);
          return;
        }

        // 每30秒更新一次拼团状态
        if (currentGroup.value.remainingSeconds % 30 === 0) {
          await fetchGroupBuyStatus(currentGroup.value.id);
        }

        // 确保 requiredSize 至少为 5
        currentGroup.value.requiredSize = currentGroup.value.requiredSize || 5;
        const currentSize = Number(currentGroup.value.currentSize);
        const requiredSize = Number(currentGroup.value.requiredSize);
        console.log(`拼团${currentGroup.value.id}倒计时检查 - 当前人数:${currentSize}, 要求人数:${requiredSize}, 剩余时间:${currentGroup.value.remainingSeconds}`);
        if (currentGroup.value.remainingSeconds <= 0) {
          clearInterval(timer);
          if (currentSize < requiredSize) {
            console.log(`拼团${currentGroup.value.id}时间到期且人数未达标，标记为失败`);
            currentGroup.value.status = "FAILED";

            // 处理退款
            try {
              const token = localStorage.getItem("token");
              await axios.post(`${API_BASE_URL}/api/group-buys/${currentGroup.value.id}/refund`, {}, {
                headers: {
                  Authorization: `Bearer ${token}`
                }
              });
              ElMessage.warning("拼团失败，已自动退款到您的账户");
            } catch (error) {
              console.error("退款处理失败:", error);
              ElMessage.error("退款处理失败，请联系客服");
            }
          }
          return;
        }
        if (currentSize === requiredSize) {
          clearInterval(timer);
          console.log(`拼团${currentGroup.value.id}达到人数要求，标记为成功`);
          currentGroup.value.status = "SUCCESS";
          ElMessage.success("拼团成功！");
          return;
        }
        currentGroup.value.remainingSeconds--;
      }, 1000);

      // 保存定时器ID以便在组件销毁时清除
      timers.value[currentGroup.value.id] = timer;
    };
    const fetchGroupBuyStatus = async groupId => {
      try {
        const response = await axios.get(`${API_BASE_URL}/api/group-buys/${groupId}`, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`
          }
        });
        if (response.data.code === 200) {
          currentGroup.value = response.data.data;
        }
      } catch (error) {
        // 静默失败，不显示任何错误信息
      }
    };
    const resetGroupBuyDialog = () => {
      isGroupBuyDialogVisible.value = false;
      // 不再重置currentGroup，只在实际拼团结束时重置
      inviteCode.value = "";
      groupBuyAction.value = "";
    };

    // 加入购物车
    const addToCart = async () => {
      const quantity = 1;
      const token = localStorage.getItem("token");
      if (!token) {
        ElMessage.error("请先登录");
        return;
      }
      try {
        const response = await axios.post(`http://localhost:5000/api/cart?productId=${product.value.id}&quantity=${quantity}`, {}, {
          headers: {
            Authorization: `Bearer ${token}`
          }
        });
        if (response.data.code === 200) {
          ElMessage.success(`${product.value.name} 已加入购物车！`);
        } else {
          ElMessage.error("加入购物车失败: " + response.data.message);
        }
      } catch (error) {
        console.error("加入购物车时发生错误:", error);
        ElMessage.error("加入购物车失败，请稍后重试。");
      }
    };

    // 显示购买选项
    const showPurchaseOptions = () => {
      optionsVisible.value = true; // 显示购买选项
    };

    // 打开确认购买对话框
    const askForPurchaseConfirmation = async () => {
      try {
        console.log("开始单独购买流程...");
        groupBuyAction.value = "purchase"; // 设置为单独购买
        optionsVisible.value = false;

        // 先获取优惠券信息
        console.log("准备获取优惠券信息...");
        await fetchAvailableCoupons();
        console.log("获取优惠券后的列表:", availableCoupons.value);

        // 重置选中的优惠券
        selectedCouponId.value = null;

        // 显示购买对话框
        buyDialogVisible.value = true;
      } catch (error) {
        console.error("处理购买流程时出错:", error);
        ElMessage.error("初始化购买对话框失败");
      }
    };
    const fetchAvailableCoupons = async () => {
      try {
        const token = localStorage.getItem("token");
        if (!token) {
          ElMessage.error("请先登录");
          return;
        }
        console.log("开始获取优惠券...");
        const response = await axios.get(`${API_BASE_URL}/api/coupons/my`, {
          headers: {
            Authorization: `Bearer ${token}`
          }
        });
        console.log("优惠券API响应:", response);

        // 后端直接返回优惠券数组，不需要检查code
        const allCoupons = response.data || [];
        console.log("所有优惠券:", allCoupons);

        // 过滤出未使用的优惠券
        availableCoupons.value = allCoupons.filter(coupon => !coupon.isUsed && new Date(coupon.expiryTime) > new Date());
        console.log("可用的优惠券:", availableCoupons.value);
        if (availableCoupons.value.length === 0) {
          console.log("没有可用的优惠券");
          ElMessage.info("您暂时没有可用的优惠券");
        } else {
          console.log(`找到${availableCoupons.value.length}张可用优惠券`);
        }
      } catch (error) {
        console.error("获取优惠券时发生错误:", error);
        ElMessage.error("获取优惠券失败");
      }
    };

    // 重置对话框状态
    const resetDialog = () => {
      isDialogVisible.value = false;
    };

    // 确认购买并打开输入密码对话框
    const confirmPurchase = () => {
      isDialogVisible.value = false;
      isPasswordDialogVisible.value = true;
      console.log("确认购买时的购买方式:", groupBuyAction.value); // 添加调试日志
    };

    // 重置密码输入对话框状态
    const resetPasswordDialog = () => {
      isPasswordDialogVisible.value = false;
      paymentPassword.value = ""; // 清空密码输入
    };

    // 在 script setup 部分添加 goHome 方法
    const goHome = () => {
      router.push("/");
    };
    const getParticipantAvatar = index => {
      if (!currentGroup.value?.participants) return "/assets/avatar.png";
      const participant = Array.from(currentGroup.value.participants)[index];
      return participant?.avatar || "/assets/avatar.png";
    };
    const getParticipantName = index => {
      if (!currentGroup.value?.participants) return "用户";
      const participant = Array.from(currentGroup.value.participants)[index];
      return participant?.nickname || "用户";
    };
    const calculateTotalPrice = () => {
      let price = product.value.price * quantity.value;
      console.log("原始价格:", price);
      console.log("选中的优惠券ID:", selectedCouponId.value);
      console.log("可用优惠券列表:", availableCoupons.value);
      if (selectedCouponId.value) {
        const selectedCoupon = availableCoupons.value.find(c => c.id === selectedCouponId.value);
        console.log("选中的优惠券详情:", selectedCoupon);
        if (selectedCoupon) {
          const discountPercent = selectedCoupon.discount * 100;
          const discountedPrice = price * selectedCoupon.discount;
          console.log(`应用${discountPercent}%折扣，原价${price}，折后价${discountedPrice}`);
          return discountedPrice.toFixed(2);
        }
      }
      return price.toFixed(2);
    };
    const handleCouponChange = couponId => {
      console.log("选择的优惠券ID:", couponId);
      selectedCouponId.value = couponId;
      const selectedCoupon = availableCoupons.value.find(c => c.id === couponId);
      if (selectedCoupon) {
        const discountPercent = (selectedCoupon.discount * 100).toFixed(0);
        console.log("选择的优惠券折扣率:", selectedCoupon.discount, `(${discountPercent}%)`);
        ElMessage.success(`已选择${discountPercent}%折扣券`);
      }
    };
    const confirmBuy = async () => {
      buying.value = true;
      try {
        const token = localStorage.getItem("token");
        if (!token) {
          ElMessage.error("请先登录");
          return;
        }

        // 计算实际支付金额
        let paymentAmount = product.value.price * quantity.value;
        if (selectedCouponId.value) {
          const selectedCoupon = availableCoupons.value.find(c => c.id === selectedCouponId.value);
          if (selectedCoupon) {
            paymentAmount = paymentAmount * selectedCoupon.discount;
          }
        }
        const response = await axios.post(`${API_BASE_URL}/api/orders`, {
          userId: store.getters.userId,
          productId: product.value.id,
          quantity: quantity.value,
          paymentAmount: paymentAmount,
          paymentPassword: paymentPassword.value,
          couponId: selectedCouponId.value
        }, {
          headers: {
            Authorization: `Bearer ${token}`
          }
        });
        if (response.data.code === 200) {
          ElMessage.success("购买成功");
          buyDialogVisible.value = false;
          router.push("/orders");
        } else {
          ElMessage.error(response.data.message || "购买失败");
        }
      } catch (error) {
        console.error("购买失败:", error);
        if (error.response?.data?.message) {
          ElMessage.error(error.response.data.message);
        } else {
          ElMessage.error("购买失败，请稍后重试");
        }
      } finally {
        buying.value = false;
        paymentPassword.value = ""; // 清空支付密码
      }
    };
    const __returned__ = {
      API_BASE_URL,
      paymentPassword,
      route,
      router,
      store,
      product,
      optionsVisible,
      isDialogVisible,
      isPasswordDialogVisible,
      isGroupBuyDialogVisible,
      currentGroup,
      availableGroups,
      inviteCode,
      groupBuyAction,
      timers,
      buyDialogVisible,
      quantity,
      selectedCouponId,
      availableCoupons,
      buying,
      fetchProductDetails,
      fetchAvailableGroups,
      showGroupBuyDialog,
      createGroup,
      joinGroup,
      joinGroupByCode,
      handlePaymentSubmit,
      copyInviteCode,
      formatTime,
      startCountdown,
      fetchGroupBuyStatus,
      resetGroupBuyDialog,
      addToCart,
      showPurchaseOptions,
      askForPurchaseConfirmation,
      fetchAvailableCoupons,
      resetDialog,
      confirmPurchase,
      resetPasswordDialog,
      goHome,
      getParticipantAvatar,
      getParticipantName,
      calculateTotalPrice,
      handleCouponChange,
      confirmBuy,
      ref,
      onMounted,
      get useRoute() {
        return useRoute;
      },
      get useRouter() {
        return useRouter;
      },
      get ElButton() {
        return ElButton;
      },
      get ElDialog() {
        return ElDialog;
      },
      get ElInput() {
        return ElInput;
      },
      get ElMessage() {
        return ElMessage;
      },
      get ElAvatar() {
        return ElAvatar;
      },
      get axios() {
        return axios;
      },
      get useStore() {
        return useStore;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
